      this.getDataforFireExtinguishers(this.loginInfo.tenantID, this.globalFilterID);
      this.getTopCarbonConsumingForFireExtinguishers(this.loginInfo.tenantID, this.defaultParam, this.globalFilterID);
      this.getTopCarbonConsumingByMonthForFireExtinguishers(this.loginInfo.tenantID, this.defaultParam, this.globalFilterID);
