  isOutOfStock(data) {
    return data.inventoryStatus === 'OUTOFSTOCK';
  }
  AcceptSingleEntry() {
    if (this.loginInfo.role == 'Preparer') {
      this.notification.showWarning('You are not authorized to approve entry', 'Warning');
      return false;
    }
    const entry = this.dataEntry;
    this.sendApprovalEntries = [];
    if (entry.ID == undefined || entry.ID == null) {
      this.selectedObjectEntry = {
        // Create a new object for each iteration
        id: entry.id,
        categoryID: entry.categoryID,
        tablename: entry.tablename
      };
    } else {
      this.selectedObjectEntry = {
        // Create a new object for each iteration
        id: entry.id,
        categoryID: entry.categoryID,
        tablename: entry.tablename
      };
    }
    this.sendApprovalEntries.push(this.selectedObjectEntry); // Add the new object to the sendEntries array
    let stringfyUrlData = JSON.stringify(this.sendApprovalEntries);
    const formURlData = new URLSearchParams();
    formURlData.set('updateJson', stringfyUrlData);
    formURlData.set('categoryID', entry.categoryID);
    this.trackingService.newSendSCSingleDataforApprove(formURlData).subscribe({
      next: response => {
        // console.log(response);
        if (response.success == true) {
          this.notification.showSuccess('Entry Approved', 'Success');
          this.ALLEntries(this.facilityID);
          this.onClose2();
          this.sendApprovalEntries = [];
          this.selectedEntry = [];
        } else {
          this.notification.showWarning('Entry not Approved', 'Warning');
          this.onClose2();
        }
        this.sendApprovalEntries = [];
      },
      error: err => {
        this.notification.showError('Entry Approval Failed.', 'Error');
        this.onClose2();
        console.error('errrrrrr>>>>>>', err);
      }
    });
  }
  RejectSingleEntry() {
    const entry = this.dataEntry;
    this.sendApprovalEntries = [];
    this.selectedObjectEntry = {
      // Create a new object for each iteration
      id: entry.id,
      categoryID: entry.categoryID,
      tablename: entry.tablename,
      Reason: entry.reason
    };
    this.sendApprovalEntries.push(this.selectedObjectEntry); // Add the new object to the sendEntries array
    let stringfyUrlData = JSON.stringify(this.sendApprovalEntries);
    const formURlData = new URLSearchParams();
    formURlData.set('updateJson', stringfyUrlData);
    formURlData.set('categoryID', entry.categoryID);
    this.trackingService.newSendDeleteSingleDataforApprove(formURlData).subscribe({
      next: response => {
        if (response.success == true) {
          this.notification.showSuccess('Entry Rejected', 'Success');
          this.ALLEntries(this.facilityID);
          this.visible = false;
          this.onClose2();
          this.selectedEntry = [];
          this.sendApprovalEntries = [];
        } else {
          this.notification.showWarning('Entry not Rejected', 'Warning');
        }
        this.sendApprovalEntries = [];
      },
      error: err => {
        this.notification.showError('Entry Rejection Failed.', 'Error');
        console.error('errrrrrr>>>>>>', err);
      }
    });
    return;
  }
  downloadFile(fileName) {
    if (fileName) {
      this.trackingService.downloadFile(fileName).subscribe(response => {
        const url = window.URL.createObjectURL(response);
        const a = document.createElement('a');
        a.href = url;
        a.download = fileName; // Specify the desired file name
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        window.URL.revokeObjectURL(url);
        this.toastr.success('Doc downloaded successfully');
      }, error => {
        console.error('Error downloading the file.', error);
        this.toastr.error('Error downloading the file.');
      });
    } else {
      this.toastr.warning('File not found!');
    }
  }
  FilterByYear() {
    this.ALLEntries(this.facilityID);
  }
