  onCompanyUpload(event, fileUpload) {
    const file = event[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = e => {
      const data = new Uint8Array(e.target.result);
      const workbook = xlsx__WEBPACK_IMPORTED_MODULE_21__.read(data, {
        type: 'array'
      });
      const sheetName = workbook.SheetNames[0];
      const worksheet = workbook.Sheets[sheetName];
      this.jsonCompanyData = xlsx__WEBPACK_IMPORTED_MODULE_21__.utils.sheet_to_json(worksheet, {
        header: 1
      });
      const jsonReading = this.convertToKeyValue(this.jsonCompanyData);
      this.jsonCompanyData = jsonReading.filter(items => {
        return items['Vehicle Model'] !== '';
      });
      this.jsonCompanyData = this.jsonCompanyData.map(item => {
        return {
          vehicleType: item['Vehicle Model'],
          noOfVehicles: item['No of Vehicles'],
          tripsPerVehicle: item['Trips per vehicle'],
          modeOfEntry: item['Mode of data entry'],
          value: item['Value'] ? item['Value'] : '',
          unit: item['Unit'] ? item['Unit'] : ''
        };
      });
      // console.log(this.jsonData);
      setTimeout(() => {
        fileUpload.clear();
      }, 1000);
    };
    reader.readAsArrayBuffer(file);
  }
  convertToKeyValue(data) {
    if (data.length < 2) return [];
    const headers = data[0]; // Extract headers
    return data.slice(1).map(row => {
      let obj = {};
      headers.forEach((header, index) => {
        let value = row[index] || '';
        // Convert Excel date serial number to readable date
        if (header.includes('Date') && typeof value === 'number') {
          value = xlsx__WEBPACK_IMPORTED_MODULE_21__.SSF.format('dd-mm-yyyy', value); // Converts to "dd-mm-yyyy"
        }
        obj[header] = value;
      });
      return obj;
    });
  }
