      this.GetAllFacility();
      this.getDataforVehicles(this.loginInfo.tenantID, this.globalFilterID);
      this.getTopCarbonConsumingForVehicles(this.loginInfo.tenantID, this.defaultParam, this.globalFilterID);
      this.getTopCarbonConsumingByMonthForVehicles(this.loginInfo.tenantID, this.defaultParam, this.globalFilterID);
